import{_ as a,o as t,c as r,a6 as o}from"./chunks/framework.De615z8S.js";const f=JSON.parse('{"title":"Shopify产品页：媒体顺序与准确文字","description":"","frontmatter":{"id":"shopify-product","title":"Shopify产品页：媒体顺序与准确文字","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","detail-image-workflow","cross-border-knowledge"],"platform_rule_ids":["shopify"],"order":23.3},"headers":[],"relativePath":"ecommerce/shopify-product.md","filePath":"ecommerce/shopify-product.md"}'),i={name:"ecommerce/shopify-product.md"};function p(s,e,h,l,d,n){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="shopify产品页-媒体顺序与准确文字" tabindex="-1">Shopify产品页：媒体顺序与准确文字 <a class="header-anchor" href="#shopify产品页-媒体顺序与准确文字" aria-label="Permalink to &quot;Shopify产品页：媒体顺序与准确文字&quot;">​</a></h1><p>Shopify产品媒体承担商品解释，主题决定显示方式。先做一套商品媒体，再看产品页、集合页和手机；不要把首页横幅的上传限制直接套到产品图片。</p><h2 id="第1步-分清上传入口" tabindex="-1">第1步：分清上传入口 <a class="header-anchor" href="#第1步-分清上传入口" aria-label="Permalink to &quot;第1步：分清上传入口&quot;">​</a></h2><p>当前官方产品媒体文档列出产品／集合图片的尺寸与体积要求，推荐方图可用2048×2048；具体显示取决于主题。<a href="https://help.shopify.com/en/manual/products/product-media/product-media-types" target="_blank" rel="noreferrer">产品媒体说明</a>。本教程把2048方图作为练习母版，不宣称它适用于所有图片区块。</p><p>通用图片说明另列上传限制，还注明产品图片存在不同限制。核对时记录是产品媒体、集合图片，还是主题中的首页／幻灯片素材。<a href="https://help.shopify.com/en/manual/online-store/images/theme-images" target="_blank" rel="noreferrer">通用图片说明</a>。</p><h2 id="第2步-安排图片顺序" tabindex="-1">第2步：安排图片顺序 <a class="header-anchor" href="#第2步-安排图片顺序" aria-label="Permalink to &quot;第2步：安排图片顺序&quot;">​</a></h2><p>DN01可以按“整体识别→开盖结构→书桌场景→尺寸→发货内容→使用”排列。这是教程示范顺序，张数和第一张选择按你的买家任务与主题检查。商品主体在整套里保持颜色、结构和比例。</p><p>使用<a href="/ai-visual-creation-handbook/prompts/P13">P13产品媒体</a>生成逐张任务、准确短文案和alt text。第一张缩略图要能识别商品；细节图需要真实近照，不能用生成的隐藏结构充数。</p><h2 id="第3步-把文字放到合适的位置" tabindex="-1">第3步：把文字放到合适的位置 <a class="header-anchor" href="#第3步-把文字放到合适的位置" aria-label="Permalink to &quot;第3步：把文字放到合适的位置&quot;">​</a></h2><p>较长规格和使用说明放在产品文本、主题区块或可编辑表格中。图片中文字只保留必要的尺寸或结构标签，手机缩小后仍能看清。产品变体使用各自真实照片，不能把白色版本重染成未经确认的灰色SKU。</p><p>alt text描述图片实际内容，不堆关键词。示例：“White DeskNest DN01 desk organizer with lid and one removable divider.”这句话仅用于虚构练习；正式内容依照实际商品和图中对象填写。<a href="https://help.shopify.com/en/manual/products/product-media/add-alt-text" target="_blank" rel="noreferrer">官方alt text说明</a>。</p><h2 id="第4步-实际主题预览" tabindex="-1">第4步：实际主题预览 <a class="header-anchor" href="#第4步-实际主题预览" aria-label="Permalink to &quot;第4步：实际主题预览&quot;">​</a></h2><p>在产品页与集合页检查：首图缩略、同排图片的比例、放大查看、图文区块顺序、变体切换、手机裁切和读取。准确的母版在主题里仍可能被裁掉，调整图片焦点或重新安排构图。</p><p>交付包括媒体顺序、各张图片、准确文案、alt text表和主题预览记录。尚未进入实际Shopify商店时，不把本地HTML预览写成主题验证完成。</p>',14)])])}const m=a(i,[["render",p]]);export{f as __pageData,m as default};
